class SharedImageState:
    def __init__(self) -> None:
        self.current_image: Optional[MSIImage] = None
        self.tic_image: Optional[np.ndarray] = None
        self.ion_image: Optional[np.ndarray] = None
        self.mzml_folder: Optional[Path] = None
        # Keep recently viewed ion images in memory without allowing a large
        # feature project to grow until the process runs out of RAM.
        self.cached_images: OrderedDict[str, np.ndarray] = OrderedDict()
        self.memory_cache_limit_bytes: int = 256 * 1024 * 1024
        self.project_cache_folder: Optional[Path] = None
        self.cancel_requested: bool = False
        self.rois: list[dict] = []
        self.feature_table: pd.DataFrame = pd.DataFrame()
        self.roi_feature_table: pd.DataFrame = pd.DataFrame()
        self.load_or_build_ion_image = None
        self.optical_image: Optional[np.ndarray] = None
        self.optical_image_path: Optional[Path] = None
        self.optical_full_image: Optional[np.ndarray] = None
        self.brightfield_image: Optional[np.ndarray] = None
        self.brightfield_image_path: Optional[Path] = None
        self.brightfield_full_image: Optional[np.ndarray] = None
        self.gfp_image: Optional[np.ndarray] = None
        self.gfp_image_path: Optional[Path] = None
        self.gfp_full_image: Optional[np.ndarray] = None
        self.optical_crop_rect: Optional[tuple[int, int, int, int]] = None
        self.alignment_matrix: Optional[np.ndarray] = None
        self.alignment_metadata: dict = {}
        self.msi_crop_rect: Optional[tuple[int, int, int, int]] = None
        self.current_image_full: Optional[MSIImage] = None
        self.annotation_table: pd.DataFrame = pd.DataFrame()
        self.loaded_roi_datasets: list[dict] = []
        # Shared display/cache preferences so secondary MSI viewers can match the main Data tab.
        self.display_mode: str = "Physical aspect"
        self.display_cmap: str = "viridis"
        self.display_log_scale: bool = False
        # Display-only contrast window. Fractions are normalized to the current
        # image's linear/log display range so the same slider positions remain
        # useful when switching between ions with very different intensities.
        self.display_intensity_min_fraction: float = 0.0
        self.display_intensity_max_fraction: float = 1.0
        self.display_intensity_mode: str = "Absolute range"
        self.display_x_size_mm: float = 1.32
        self.display_y_size_mm: float = 1.01
        self.alignment_reference_mode: str = "Current selected MSI"
        self.cache_mode: str = "Raw cached images"
        # Acquisition polarity is shared by reconstruction, feature detection,
        # image caching, ROI extraction, and saved projects. Keeping it in the
        # shared state prevents mixed-polarity data from leaking between tabs.
        self.acquisition_polarity: str = "Positive mode (+)"
        self.manual_roi_optical_image: Optional[np.ndarray] = None
        self.manual_roi_optical_image_path: Optional[Path] = None

    def get_memory_cached_image(self, cache_id: str) -> Optional[np.ndarray]:
        image = self.cached_images.get(cache_id)
        if image is not None:
            self.cached_images.move_to_end(cache_id)
        return image

    def store_memory_cached_image(self, cache_id: str, image: np.ndarray) -> None:
        """Store one ion image in a bounded least-recently-used memory cache."""
        array = np.asarray(image)
        if int(array.nbytes) > self.memory_cache_limit_bytes:
            return
        self.cached_images.pop(cache_id, None)
        self.cached_images[cache_id] = image
        total_bytes = sum(int(np.asarray(value).nbytes) for value in self.cached_images.values())
        while total_bytes > self.memory_cache_limit_bytes and len(self.cached_images) > 1:
            _old_key, old_image = self.cached_images.popitem(last=False)
            total_bytes -= int(np.asarray(old_image).nbytes)


def apply_crop_to_array(image: np.ndarray, crop_rect: Optional[tuple[int, int, int, int]]) -> np.ndarray:
    """Return image cropped to x1,y1,x2,y2 if a crop is active. x2/y2 are exclusive."""
    arr = np.asarray(image)
    normalized = normalize_crop_rect(crop_rect, arr.shape[:2])
    if normalized is None:
        return arr
    x1, y1, x2, y2 = normalized
    return np.array(arr[y1:y2, x1:x2], copy=True)


def normalize_crop_rect(
    crop_rect: Optional[tuple[int, int, int, int]],
    image_shape: tuple[int, int],
) -> Optional[tuple[int, int, int, int]]:
    """Clamp an exclusive-edge crop rectangle to an image shape."""
    if crop_rect is None:
        return None
    h, w = image_shape[:2]
    if h <= 0 or w <= 0:
        return None
    x1, y1, x2, y2 = crop_rect
    x1 = max(0, min(int(x1), w - 1))
    y1 = max(0, min(int(y1), h - 1))
    x2 = max(x1 + 1, min(int(x2), w))
    y2 = max(y1 + 1, min(int(y2), h))
    return x1, y1, x2, y2


def crop_origin(crop_rect: Optional[tuple[int, int, int, int]]) -> tuple[int, int]:
    """Return the full-image origin of a cropped view."""
    if crop_rect is None:
        return 0, 0
    return int(crop_rect[0]), int(crop_rect[1])


def view_mask_to_full(
    view_mask: np.ndarray,
    full_shape: tuple[int, int],
    crop_rect: Optional[tuple[int, int, int, int]],
) -> np.ndarray:
    """Embed a cropped-view mask into full-image coordinates."""
    mask = np.asarray(view_mask, dtype=bool)
    normalized = normalize_crop_rect(crop_rect, full_shape)
    if normalized is None:
        if mask.shape != tuple(full_shape[:2]):
            raise ValueError(f"View mask shape {mask.shape} does not match full image shape {tuple(full_shape[:2])}.")
        return np.array(mask, copy=True)
    x1, y1, x2, y2 = normalized
    expected = (y2 - y1, x2 - x1)
    if mask.shape != expected:
        raise ValueError(f"View mask shape {mask.shape} does not match active crop shape {expected}.")
    full_mask = np.zeros(tuple(full_shape[:2]), dtype=bool)
    full_mask[y1:y2, x1:x2] = mask
    return full_mask


def full_mask_to_view(
    full_mask: np.ndarray,
    crop_rect: Optional[tuple[int, int, int, int]],
) -> np.ndarray:
    """Return the visible portion of a full-image ROI mask."""
    return np.asarray(apply_crop_to_array(np.asarray(full_mask, dtype=bool), crop_rect), dtype=bool)


def translate_vertices(
    vertices: list[tuple[float, float]],
    dx: float,
    dy: float,
) -> list[tuple[float, float]]:
    return [(float(x) + float(dx), float(y) + float(dy)) for x, y in vertices]


def crop_intensity_statistics(image: np.ndarray, crop_rect: Optional[tuple[int, int, int, int]]) -> dict:
    """Calculate display/feature statistics using only pixels inside the active crop."""
    cropped = np.asarray(apply_crop_to_array(image, crop_rect), dtype=float)
    finite = cropped[np.isfinite(cropped)]
    if finite.size == 0:
        return {
            "max_intensity": 0.0,
            "total_intensity": 0.0,
            "detection_count": 0,
            "display_min": 0.0,
            "display_max": 0.0,
        }
    positive = finite[finite > 0]
    display_source = positive if positive.size else finite
    return {
        "max_intensity": float(np.max(finite)),
        "total_intensity": float(np.sum(finite)),
        "detection_count": int(np.count_nonzero(finite)),
        "display_min": float(np.min(display_source)),
        "display_max": float(np.max(display_source)),
    }


def inclusion_value(value) -> bool:
    """Interpret CSV/project inclusion values consistently."""
    if value is None:
        return True
    if isinstance(value, (bool, np.bool_)):
        return bool(value)
    if isinstance(value, (int, float, np.integer, np.floating)):
        if pd.isna(value):
            return True
        return bool(value)
    text = str(value).strip().lower()
    if text in {"", "nan", "none"}:
        return True
    return text not in {"0", "false", "no", "n", "excluded", "exclude", "noise", "qc fail", "qc_failed"}


def is_noise_like_group(group_name: str) -> bool:
    """Identify common non-biological group labels for safe default exclusion."""
    normalized = re.sub(r"[^a-z0-9]+", "_", str(group_name).strip().lower()).strip("_")
    tokens = set(normalized.split("_"))
    return bool(
        normalized in {"noise", "background", "excluded", "exclude", "qc_fail", "qc_failed", "artifact"}
        or tokens.intersection({"noise", "background", "artifact"})
        or normalized.startswith("excluded")
        or normalized.startswith("qc_fail")
    )


def filter_roi_analysis_rows(
    table: pd.DataFrame,
    included_groups: Optional[set[str]] = None,
) -> tuple[pd.DataFrame, dict]:
    """Remove excluded ROIs and groups before any statistical preprocessing."""
    if table is None or table.empty:
        return pd.DataFrame(), {"total_rois": 0, "included_rois": 0, "excluded_rois": 0}
    df = table.copy()
    if "dataset" not in df.columns:
        df["dataset"] = "current_project"
    if "roi_name" not in df.columns:
        raise ValueError("ROI analysis input is missing the roi_name column.")
    if "group" not in df.columns:
        raise ValueError("ROI analysis input is missing the group column.")
    if "include_in_analysis" not in df.columns:
        df["include_in_analysis"] = True
    df["_analysis_sample_id"] = df["dataset"].astype(str) + "::" + df["roi_name"].astype(str)
    row_inclusion = df["include_in_analysis"].map(inclusion_value).astype(bool)
    sample_inclusion = row_inclusion.groupby(df["_analysis_sample_id"]).transform("all")
    include_mask = sample_inclusion.astype(bool)
    if included_groups is not None:
        normalized_groups = {str(group) for group in included_groups}
        include_mask &= df["group"].astype(str).isin(normalized_groups)
    all_samples = set(df["_analysis_sample_id"].astype(str))
    filtered = df.loc[include_mask].copy()
    included_samples = set(filtered["_analysis_sample_id"].astype(str))
    summary = {
        "total_rois": len(all_samples),
        "included_rois": len(included_samples),
        "excluded_rois": len(all_samples - included_samples),
    }
    return filtered.drop(columns=["_analysis_sample_id"], errors="ignore"), summary


class SortableTableWidgetItem(QTableWidgetItem):
    """Table item that sorts by its typed UserRole value instead of display text."""

    def __lt__(self, other) -> bool:
        left = self.data(Qt.UserRole)
        right = other.data(Qt.UserRole) if isinstance(other, QTableWidgetItem) else None
        try:
            if left is None:
                return right is not None
            if right is None:
                return False
            return left < right
        except Exception:
            return str(left) < str(right)


def natural_sort_key(path_or_name) -> list:
    name = Path(path_or_name).name
    return [int(text) if text.isdigit() else text.lower() for text in re.split(r"(\d+)", name)]


def find_raw_files(raw_folder: Path) -> list[Path]:
    return sorted(raw_folder.glob("*.raw"), key=natural_sort_key)


def find_mzml_files(mzml_folder: Path) -> list[Path]:
    return sorted(mzml_folder.glob("*.mzML"), key=natural_sort_key)


def safe_mz_name(mz: float) -> str:
    return f"mz_{mz:.5f}".replace(".", "p")


def image_display_settings(display_mode: str, x_size_mm: float, y_size_mm: float):
    if display_mode == "Fill panel":
        return {"extent": None, "aspect": "auto", "xlabel": "X pixel", "ylabel": "Y row", "box_aspect": None}
    if display_mode == "Pixel equal":
        return {"extent": None, "aspect": "equal", "xlabel": "X pixel", "ylabel": "Y row", "box_aspect": None}
    x_size_mm = max(float(x_size_mm), 0.0001)
    y_size_mm = max(float(y_size_mm), 0.0001)
    return {"extent": [0, x_size_mm, y_size_mm, 0], "aspect": "equal", "xlabel": "X position (mm)", "ylabel": "Y position (mm)", "box_aspect": y_size_mm / x_size_mm}


def display_domain_array(image: np.ndarray, log_scale: bool = False) -> np.ndarray:
    """Return the matrix actually used for MSI display, without changing source intensities."""
    arr = np.asarray(image, dtype=float)
    return np.log1p(np.clip(arr, a_min=0, a_max=None)) if log_scale else arr


def shared_display_clim_for_image(
    image: np.ndarray,
    shared_state: "SharedImageState",
    log_scale: Optional[bool] = None,
) -> tuple[float, float]:
    """Calculate the shared display-only MSI contrast window for any ROI/viewer canvas."""
    use_log = bool(shared_state.display_log_scale if log_scale is None else log_scale)
    display = display_domain_array(image, use_log)
    finite = display[np.isfinite(display)]
    if not finite.size:
        return 0.0, 1.0
    low_fraction = float(np.clip(getattr(shared_state, "display_intensity_min_fraction", 0.0), 0.0, 1.0))
    high_fraction = float(np.clip(getattr(shared_state, "display_intensity_max_fraction", 1.0), 0.0, 1.0))
    if high_fraction <= low_fraction:
        high_fraction = min(1.0, low_fraction + 0.001)
    mode = str(getattr(shared_state, "display_intensity_mode", "Absolute range"))
    if mode.startswith("Percentile"):
        vmin = float(np.nanpercentile(finite, low_fraction * 100.0))
        vmax = float(np.nanpercentile(finite, high_fraction * 100.0))
    else:
        observed_min = float(np.min(finite))
        data_min = min(0.0, observed_min)
        data_max = float(np.max(finite))
        span = data_max - data_min
        if span <= 0:
            return data_min, data_min + max(abs(data_min) * 1e-12, 1e-12)
        vmin = data_min + span * low_fraction
        vmax = data_min + span * high_fraction
    if vmax <= vmin:
        vmax = vmin + max(abs(vmin) * 1e-12, 1e-12)
    return float(vmin), float(vmax)


def split_msi_display_title(title: str) -> tuple[str, str]:
    """Keep the scientific title prominent and move processing provenance to a smaller subtitle."""
    text = str(title or "MSI image")
    parts = [part.strip() for part in text.split("|") if part.strip()]
    if not parts:
        return "MSI image", ""
    main = parts[0]
    subtitle = " • ".join(parts[1:])
    return main, subtitle


def polygon_mask_from_vertices(vertices: list[tuple[float, float]], shape: tuple[int, int]) -> np.ndarray:
    height, width = shape
    yy, xx = np.mgrid[0:height, 0:width]
    points = np.vstack((xx.ravel(), yy.ravel())).T
    path = MplPath(vertices)
    return path.contains_points(points).reshape((height, width))

def remove_small_objects_safe(mask: np.ndarray, min_size: int) -> np.ndarray:
    """Remove small connected objects while staying compatible with old/new scikit-image APIs.

    scikit-image 0.26 renamed/deprecated the min_size argument in some builds.
    This wrapper first tries the newer max_size behavior, then falls back to
    min_size, while suppressing non-actionable FutureWarnings in the user log.
    """
    arr = np.asarray(mask, dtype=bool)
    if morphology is None:
        return arr
    n = max(1, int(min_size))
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", FutureWarning)
        try:
            # Newer behavior removes objects smaller than or equal to max_size.
            # Use n-1 to mimic older min_size semantics: remove objects smaller than n.
            return morphology.remove_small_objects(arr, max_size=max(0, n - 1)).astype(bool)
        except TypeError:
            return morphology.remove_small_objects(arr, min_size=n).astype(bool)


def separated_object_labels(mask: np.ndarray, min_distance: int = 8, use_watershed: bool = True) -> np.ndarray:
    """Label binary objects, optionally separating touching objects by watershed."""
    binary = np.asarray(mask, dtype=bool)
    if binary.ndim != 2 or not np.any(binary):
        return np.zeros(binary.shape, dtype=np.int32)
    if measure is None:
        labels, _count = ndi.label(binary)
        return np.asarray(labels, dtype=np.int32)
    if not use_watershed or feature is None or segmentation is None:
        return measure.label(binary).astype(np.int32)
    distance = ndi.distance_transform_edt(binary)
    coordinates = feature.peak_local_max(
        distance,
        labels=binary,
        min_distance=max(1, int(min_distance)),
        exclude_border=False,
    )
    markers = np.zeros(binary.shape, dtype=np.int32)
    if coordinates.size:
        markers[tuple(coordinates.T)] = np.arange(1, len(coordinates) + 1, dtype=np.int32)
    if int(markers.max()) < 2:
        return measure.label(binary).astype(np.int32)
    return np.asarray(segmentation.watershed(-distance, markers, mask=binary), dtype=np.int32)


def normalized_rgb_image(image: np.ndarray) -> np.ndarray:
    """Return an RGB image scaled to 0-1 without changing channel relationships."""
    data = np.asarray(image)
    if data.ndim != 3 or data.shape[2] < 3:
        raise ValueError(
            "Automatic GFP labeling requires a color brightfield + GFP overlay image."
        )
    rgb = np.asarray(data[..., :3], dtype=float)
    finite = rgb[np.isfinite(rgb)]
    if not finite.size:
        return np.zeros(rgb.shape, dtype=float)
    low, high = np.nanpercentile(finite, [0.1, 99.9])
    if not np.isfinite(low) or not np.isfinite(high) or high <= low:
        return np.zeros(rgb.shape, dtype=float)
    scaled = np.clip((rgb - low) / (high - low), 0.0, 1.0)
    for channel in range(3):
        channel_data = scaled[..., channel]
        channel_finite = np.isfinite(channel_data)
        fill_value = (
            float(np.nanmedian(channel_data[channel_finite]))
            if np.any(channel_finite)
            else 0.0
        )
        channel_data[~channel_finite] = fill_value
    return scaled


def robust_unit_scale(values: np.ndarray, valid_mask: Optional[np.ndarray] = None) -> np.ndarray:
    """Robustly scale an image to 0-1 while ignoring invalid/artifact pixels."""
    data = np.asarray(values, dtype=float)
    finite = np.isfinite(data)
    if valid_mask is not None:
        finite &= np.asarray(valid_mask, dtype=bool)
    sample = data[finite]
    if not sample.size:
        return np.zeros(data.shape, dtype=float)
    low, high = np.nanpercentile(sample, [2.0, 99.5])
    if not np.isfinite(low) or not np.isfinite(high) or high <= low:
        return np.zeros(data.shape, dtype=float)
    return np.clip((data - low) / (high - low), 0.0, 1.0)


def composite_grid_artifact_mask(
    rgb: np.ndarray,
    min_cell_area: int,
    max_cell_area: int,
) -> np.ndarray:
    """Mask large nearly-black grid/positioning marks without masking ordinary cells."""
    if measure is None:
        return np.zeros(np.asarray(rgb).shape[:2], dtype=bool)
    data = np.asarray(rgb, dtype=float)
    rb_luminance = 0.5 * (data[..., 0] + data[..., 2])
    nearly_black = rb_luminance <= 0.045
    nearly_black = ndi.binary_closing(nearly_black, structure=np.ones((3, 3), dtype=bool))
    labels = measure.label(nearly_black)
    artifact_mask = np.zeros(nearly_black.shape, dtype=bool)
    image_area = int(nearly_black.size)
    size_floor = max(
        200,
        int(min_cell_area) * 10,
        int(max_cell_area * 1.35) if int(max_cell_area) > 0 else 0,
        int(image_area * 0.0005),
    )
    for region in measure.regionprops(labels):
        area = int(region.area)
        minr, minc, maxr, maxc = region.bbox
        height = maxr - minr
        width = maxc - minc
        long_line = max(height, width) >= 0.35 * max(nearly_black.shape)
        thin_line = min(height, width) <= max(5, int(0.02 * min(nearly_black.shape)))
        if area >= size_floor or (long_line and thin_line):
            artifact_mask[labels == region.label] = True
    if np.any(artifact_mask):
        # Grid squares are holes enclosed by the black grid network. Filling
        # those holes prevents fluorescence or texture inside positioning
        # marks from being accepted as cells.
        artifact_mask = ndi.binary_fill_holes(artifact_mask)
        artifact_mask = ndi.binary_dilation(artifact_mask, iterations=3)
    return np.asarray(artifact_mask, dtype=bool)


def split_touching_composite_cell_labels(
    mask: np.ndarray,
    detection_score: np.ndarray,
    *,
    min_distance: int,
    min_area: int,
    max_area: int,
    enabled: bool = True,
    cancel_callback=None,
) -> tuple[np.ndarray, np.ndarray, dict[int, int]]:
    """Split merged cell clusters and retain the parent-cluster relationship."""
    binary = np.asarray(mask, dtype=bool)
    if measure is None:
        labels, _count = ndi.label(binary)
        labels = np.asarray(labels, dtype=np.int32)
        counts = {int(value): 1 for value in np.unique(labels) if int(value) > 0}
        return labels, labels.copy(), counts
    parent_labels = measure.label(binary).astype(np.int32)
    parent_regions = list(measure.regionprops(parent_labels))
    if not enabled or feature is None or segmentation is None or not parent_regions:
        counts = {int(region.label): 1 for region in parent_regions}
        return parent_labels.copy(), parent_labels, counts

    plausible_areas = np.asarray(
        [
            float(region.area)
            for region in parent_regions
            if float(region.area) >= float(min_area)
            and (int(max_area) <= 0 or float(region.area) <= float(max_area))
        ],
        dtype=float,
    )
    if plausible_areas.size:
        typical_area = float(np.nanpercentile(plausible_areas, 40.0))
    else:
        typical_area = float(np.pi * max(2.0, float(min_distance)) ** 2)
    typical_area = max(typical_area, float(min_area) * 1.25, 4.0)

    final_labels = np.zeros(binary.shape, dtype=np.int32)
    next_label = 1
    cluster_counts: dict[int, int] = {}
    score = robust_unit_scale(np.asarray(detection_score, dtype=float), binary)
    separation = max(1, int(min_distance))

    for parent_index, parent in enumerate(parent_regions):
        if (
            parent_index % 10 == 0
            and cancel_callback is not None
            and bool(cancel_callback())
        ):
            raise RuntimeError("Composite cell preview was cancelled.")
        component = parent_labels == int(parent.label)
        area = float(parent.area)
        distance = ndi.distance_transform_edt(component)
        max_distance = float(np.max(distance)) if np.any(component) else 0.0
        distance_peaks = feature.peak_local_max(
            distance,
            labels=component,
            min_distance=separation,
            threshold_abs=max(1.0, 0.22 * max_distance),
            exclude_border=False,
        )
        score_peaks = feature.peak_local_max(
            ndi.gaussian_filter(score, sigma=1.0),
            labels=component,
            min_distance=separation,
            threshold_rel=0.35,
            exclude_border=False,
        )

        candidates = []
        seen = set()
        for source_rank, coordinates in enumerate((distance_peaks, score_peaks)):
            for row, col in coordinates:
                key = (int(row), int(col))
                if key in seen:
                    continue
                seen.add(key)
                quality = (
                    float(distance[key]) / max(max_distance, 1e-6)
                    + 0.35 * float(score[key])
                    - 0.05 * source_rank
                )
                candidates.append((quality, key))
        candidates.sort(reverse=True)

        area_ratio = area / typical_area
        expected_cells = 1 if area_ratio < 1.45 else max(2, int(round(area_ratio)))
        # Distinct distance-transform peaks are direct evidence of multiple cell
        # centers even when the entire field contains only one merged cluster and
        # no singleton objects are available for estimating typical cell area.
        expected_cells = max(expected_cells, min(len(distance_peaks), 12))
        expected_cells = min(expected_cells, 12)
        selected: list[tuple[int, int]] = []
        minimum_seed_spacing = max(1.0, 0.70 * separation)
        for _quality, candidate in candidates:
            if all(
                np.hypot(candidate[0] - other[0], candidate[1] - other[1])
                >= minimum_seed_spacing
                for other in selected
            ):
                selected.append(candidate)
            if len(selected) >= expected_cells:
                break

        if len(selected) < 2:
            final_labels[component] = next_label
            cluster_counts[int(parent.label)] = 1
            next_label += 1
            continue

        markers = np.zeros(binary.shape, dtype=np.int32)
        for marker_id, (row, col) in enumerate(selected, start=1):
            markers[row, col] = marker_id
        watershed_surface = -distance + 0.20 * (1.0 - score)
        split = np.asarray(
            segmentation.watershed(watershed_surface, markers, mask=component),
            dtype=np.int32,
        )
        child_count = 0
        for child_label in range(1, int(np.max(split)) + 1):
            child = split == child_label
            if not np.any(child):
                continue
            final_labels[child] = next_label
            next_label += 1
            child_count += 1
        cluster_counts[int(parent.label)] = max(1, child_count)

    return final_labels, parent_labels, cluster_counts


def detect_and_classify_composite_cells(
    image: np.ndarray,
    *,
    min_area: int = 20,
    max_area: int = 5000,
    background_sigma: float = 18.0,
    min_distance: int = 8,
    detection_sensitivity: float = 5.0,
    min_circularity: float = 0.10,
    min_solidity: float = 0.45,
    max_elongation: float = 8.0,
    exclude_border: bool = True,
    exclude_grid_artifacts: bool = True,
    separate_touching_cells: bool = True,
    automatic_gfp_threshold: bool = True,
    manual_gfp_threshold: float = 0.08,
    gfp_min_fraction: float = 0.08,
    uncertain_margin: float = 0.25,
    progress_callback=None,
    cancel_callback=None,
) -> tuple[list[dict], dict]:
    """Original, model-free detector for merged brightfield + GFP microscopy images.

    Cell structure is detected from the red/blue channels so the green overlay
    cannot manufacture ordinary cell candidates. GFP is then identified as a
    connected patch whose green channel clearly exceeds both red and blue.
    """
    if measure is None or filters is None or morphology is None:
        raise RuntimeError(
            "The existing scikit-image dependency is required for composite cell detection."
        )
    def checkpoint(message: str) -> None:
        if cancel_callback is not None and bool(cancel_callback()):
            raise RuntimeError("Composite cell preview was cancelled.")
        if progress_callback is not None:
            progress_callback(message)

    checkpoint("Preparing the full-resolution optical image...")
    rgb = normalized_rgb_image(image)
    min_area = max(1, int(min_area))
    max_area = max(0, int(max_area))
    sensitivity = float(np.clip(detection_sensitivity, 1.0, 10.0))
    checkpoint("Suppressing grid marks and GFP interference...")
    artifact_mask = (
        composite_grid_artifact_mask(rgb, min_area, max_area)
        if exclude_grid_artifacts
        else np.zeros(rgb.shape[:2], dtype=bool)
    )
    valid_mask = ~artifact_mask

    checkpoint("Finding cell structure...")
    # Suppress GFP by omitting the green channel from the structural image.
    rb_gray = 0.5 * (rgb[..., 0] + rgb[..., 2])
    rb_gray = ndi.gaussian_filter(rb_gray, sigma=0.8)
    background = ndi.gaussian_filter(rb_gray, sigma=max(2.0, float(background_sigma)))
    dark_contrast = np.maximum(background - rb_gray, 0.0)
    edge_contrast = ndi.gaussian_gradient_magnitude(rb_gray, sigma=1.0)
    dark_score = robust_unit_scale(dark_contrast, valid_mask)
    edge_score = robust_unit_scale(edge_contrast, valid_mask)
    detection_score = (0.82 * dark_score) + (0.18 * edge_score)
    detection_score[artifact_mask] = 0.0

    valid_values = detection_score[valid_mask & np.isfinite(detection_score)]
    if not valid_values.size or float(np.nanmax(valid_values)) <= 0:
        return [], {
            "detection_threshold": 1.0,
            "gfp_threshold": float(manual_gfp_threshold),
            "artifact_fraction": float(np.mean(artifact_mask)),
            "accepted_count": 0,
            "rejected_count": 0,
            "cells_from_touching_clusters": 0,
            "touching_cluster_count": 0,
        }
    percentile = float(np.clip(88.0 - 3.0 * (sensitivity - 5.0), 62.0, 96.0))
    percentile_threshold = float(np.nanpercentile(valid_values, percentile))
    try:
        otsu_threshold = float(filters.threshold_otsu(valid_values))
    except Exception:
        otsu_threshold = percentile_threshold
    detection_threshold = float(
        np.clip((0.60 * otsu_threshold) + (0.40 * percentile_threshold), 0.01, 0.99)
    )
    cell_mask = detection_score >= detection_threshold
    cell_mask &= valid_mask
    cell_mask = ndi.binary_closing(cell_mask, structure=np.ones((3, 3), dtype=bool))
    cell_mask = ndi.binary_opening(cell_mask, structure=np.ones((2, 2), dtype=bool))
    cell_mask = ndi.binary_fill_holes(cell_mask)
    cell_mask = remove_small_objects_safe(cell_mask, min_area)
    checkpoint("Separating touching cell clusters...")
    labels, parent_labels, cluster_counts = split_touching_composite_cell_labels(
        cell_mask,
        detection_score,
        min_distance=max(1, int(min_distance)),
        min_area=min_area,
        max_area=max_area,
        enabled=bool(separate_touching_cells),
        cancel_callback=cancel_callback,
    )

    checkpoint("Filtering cell candidates...")
    accepted_regions = []
    rejected_count = 0
    height, width = cell_mask.shape
    for region_index, region in enumerate(measure.regionprops(labels)):
        if region_index % 50 == 0:
            checkpoint("Filtering cell candidates...")
        area = float(region.area)
        minr, minc, maxr, maxc = region.bbox
        rejected = area < min_area or (max_area > 0 and area > max_area)
        if exclude_border and (
            minr <= 1 or minc <= 1 or maxr >= height - 1 or maxc >= width - 1
        ):
            rejected = True
        component = labels == region.label
        if np.any(artifact_mask & component):
            rejected = True
        perimeter = float(region.perimeter)
        circularity = float(4.0 * np.pi * area / (perimeter * perimeter)) if perimeter > 0 else 0.0
        solidity = float(region.solidity) if np.isfinite(region.solidity) else 0.0
        minor_axis = float(region.minor_axis_length)
        major_axis = float(region.major_axis_length)
        elongation = major_axis / minor_axis if minor_axis > 0 else float("inf")
        if (
            circularity < float(min_circularity)
            or solidity < float(min_solidity)
            or elongation > float(max_elongation)
        ):
            rejected = True
        if rejected:
            rejected_count += 1
            continue
        parent_values = parent_labels[labels == region.label]
        parent_values = parent_values[parent_values > 0]
        parent_label = int(np.bincount(parent_values).argmax()) if parent_values.size else 0
        equivalent_diameter = float(
            getattr(
                region,
                "equivalent_diameter_area",
                getattr(region, "equivalent_diameter", 2.0 * np.sqrt(area / np.pi)),
            )
        )
        accepted_regions.append(
            (
                region,
                parent_label,
                {
                    "equivalent_diameter": equivalent_diameter,
                    "circularity": circularity,
                    "solidity": solidity,
                    "elongation": elongation,
                    "brightfield_contrast": float(
                        np.nanmean(detection_score[component])
                    ),
                },
            )
        )

    checkpoint("Finding connected GFP patches...")
    red, green, blue = rgb[..., 0], rgb[..., 1], rgb[..., 2]
    comparison_channel = np.maximum(red, blue)
    # A visibly green GFP pixel must beat BOTH other channels. Subtracting their
    # average was too permissive: ordinary gray/JPEG variation could look green
    # enough to label an otherwise gray cell as GFP-positive.
    green_dominance = np.maximum(green - comparison_channel, 0.0)
    green_ratio = (green + 0.02) / (comparison_channel + 0.02)
    valid_green = green_dominance[valid_mask & np.isfinite(green_dominance)]
    if automatic_gfp_threshold and valid_green.size:
        background_limit = float(np.nanpercentile(valid_green, 90.0))
        background_values = valid_green[valid_green <= background_limit]
        if not background_values.size:
            background_values = valid_green
        baseline = float(np.nanmedian(background_values))
        mad = float(
            1.4826 * np.nanmedian(np.abs(background_values - baseline))
        )
        # The absolute floor represents visible channel dominance after the RGB
        # image has been normalized. The noise term still adapts upward for
        # overlays with a green color cast.
        gfp_threshold = float(
            np.clip(
                max(0.060, baseline + 8.0 * max(mad, 0.002)),
                0.040,
                0.40,
            )
        )
    else:
        gfp_threshold = float(np.clip(manual_gfp_threshold, 0.001, 1.0))

    min_fraction = float(np.clip(gfp_min_fraction, 0.001, 1.0))
    margin = float(np.clip(uncertain_margin, 0.0, 0.90))
    min_gfp_component_pixels = max(4, min(20, int(round(0.025 * min_area))))

    def connected_signal_mask(
        dominance_threshold: float,
        ratio_threshold: float,
        brightness_threshold: float,
        minimum_pixels: int,
    ) -> np.ndarray:
        raw = (
            (green_dominance >= float(dominance_threshold))
            & (green_ratio >= float(ratio_threshold))
            & (green >= float(brightness_threshold))
            & valid_mask
        )
        raw = ndi.binary_closing(
            raw,
            structure=ndi.generate_binary_structure(2, 1),
        )
        signal_labels, signal_count = ndi.label(raw)
        if signal_count <= 0:
            return np.zeros(raw.shape, dtype=bool)
        sizes = np.bincount(signal_labels.ravel())
        keep = sizes >= max(1, int(minimum_pixels))
        keep[0] = False
        return keep[signal_labels]

    # Strong patches are clearly green to the eye. A second, more permissive
    # mask is used only to mark borderline/dim cells as uncertain.
    green_pixel_mask = connected_signal_mask(
        gfp_threshold,
        1.12,
        0.12,
        min_gfp_component_pixels,
    )
    weak_green_pixel_mask = connected_signal_mask(
        max(0.035, 0.60 * gfp_threshold),
        1.08,
        0.10,
        max(3, int(round(0.70 * min_gfp_component_pixels))),
    )

    yy, xx = np.ogrid[:height, :width]
    # Partition nearby fluorescence by nearest cell center. This prevents a
    # GFP-positive member of a touching pair from donating green pixels to its
    # GFP-negative neighbor when their circular measurement areas overlap.
    center_ids = np.zeros((height, width), dtype=np.int32)
    for center_id, (region, _parent_label, _measurements) in enumerate(accepted_regions, start=1):
        if center_id % 100 == 0:
            checkpoint("Assigning fluorescence to the nearest detected cell...")
        center_y, center_x = region.centroid
        row = int(np.clip(round(float(center_y)), 0, height - 1))
        col = int(np.clip(round(float(center_x)), 0, width - 1))
        center_ids[row, col] = center_id
    checkpoint("Assigning fluorescence to the nearest detected cell...")
    if accepted_regions:
        _distances, nearest_indices = ndi.distance_transform_edt(
            center_ids == 0,
            return_indices=True,
        )
        nearest_center_id = center_ids[tuple(nearest_indices)]
    else:
        nearest_center_id = np.zeros((height, width), dtype=np.int32)

    checkpoint("Classifying GFP-positive and GFP-negative cells...")
    detections = []
    multi_cell_cluster_count = 0
    claimed_gfp_mask = np.zeros((height, width), dtype=bool)
    accepted_areas = np.asarray(
        [float(region.area) for region, _parent_label, _measurements in accepted_regions],
        dtype=float,
    )
    typical_area = (
        float(np.nanmedian(accepted_areas))
        if accepted_areas.size
        else max(float(min_area) * 2.0, 50.0)
    )
    typical_radius = float(
        np.clip(np.sqrt(typical_area / np.pi) * 1.35, 3.0, 100.0)
    )

    def circle_vertices(
        center_x: float,
        center_y: float,
        radius: float,
    ) -> list[tuple[float, float]]:
        angles = np.linspace(0.0, 2.0 * np.pi, 40, endpoint=False)
        return [
            (
                float(center_x + radius * np.cos(angle)),
                float(center_y + radius * np.sin(angle)),
            )
            for angle in angles
        ]

    for center_id, (region, parent_label, measurements) in enumerate(accepted_regions, start=1):
        if center_id % 50 == 0:
            checkpoint("Classifying GFP-positive and GFP-negative cells...")
        cy, cx = map(float, region.centroid)
        area = float(region.area)
        optical_radius = float(np.clip(np.sqrt(area / np.pi) * 1.35, 3.0, 100.0))
        neighborhood = ((xx - cx) ** 2 + (yy - cy) ** 2) <= optical_radius ** 2
        neighborhood &= (
            valid_mask
            & np.isfinite(green_dominance)
            & (nearest_center_id == center_id)
        )
        claimed_gfp_mask |= neighborhood & green_pixel_mask
        local_dominance = green_dominance[neighborhood]
        required_gfp_pixels = max(
            min_gfp_component_pixels,
            int(np.ceil(min_fraction * area)),
        )
        strong_gfp_pixels = int(np.count_nonzero(green_pixel_mask[neighborhood]))
        weak_gfp_pixels = int(
            np.count_nonzero(weak_green_pixel_mask[neighborhood])
        )
        if local_dominance.size:
            gfp_fraction = float(strong_gfp_pixels / max(area, 1.0))
            gfp_peak = float(np.nanpercentile(local_dominance, 95.0))
            top_count = max(1, int(np.ceil(local_dominance.size * 0.10)))
            gfp_top_mean = float(
                np.mean(
                    np.partition(local_dominance, -top_count)[-top_count:]
                )
            )
        else:
            gfp_fraction = 0.0
            gfp_peak = 0.0
            gfp_top_mean = 0.0
        classification_score = float(
            strong_gfp_pixels / max(required_gfp_pixels, 1)
        )
        weak_score = float(
            weak_gfp_pixels / max(required_gfp_pixels, 1)
        )
        # A high peak alone can no longer force a positive label. The cell must
        # contain enough pixels from a spatially connected, visibly green patch.
        if classification_score >= 1.0:
            classification = "positive"
        elif (
            classification_score >= max(0.35, 1.0 - margin)
            or weak_score >= 1.0
        ):
            classification = "uncertain"
        else:
            classification = "negative"
        if classification == "positive":
            confidence = float(
                np.clip(
                    0.55
                    + 0.30 * (classification_score - 1.0)
                    + 0.15 * max(
                        0.0,
                        gfp_top_mean / max(gfp_threshold, 1e-6) - 1.0,
                    ),
                    0.0,
                    1.0,
                )
            )
        elif classification == "negative":
            confidence = float(np.clip(1.0 - weak_score, 0.0, 1.0))
        else:
            confidence = float(
                np.clip(
                    1.0
                    - abs(classification_score - 1.0)
                    / max(0.25, 1.0 + margin),
                    0.0,
                    1.0,
                )
            )
        detections.append(
            {
                "classification": classification,
                "classification_score": classification_score,
                "confidence": confidence,
                "gfp_fraction": gfp_fraction,
                "gfp_peak_excess": gfp_peak,
                "gfp_top_mean_excess": gfp_top_mean,
                "gfp_component_pixels": strong_gfp_pixels,
                "gfp_required_pixels": required_gfp_pixels,
                "gfp_threshold": gfp_threshold,
                "centroid": (cx, cy),
                "area": area,
                "equivalent_diameter": float(measurements["equivalent_diameter"]),
                "circularity": float(measurements["circularity"]),
                "solidity": float(measurements["solidity"]),
                "elongation": float(measurements["elongation"]),
                "brightfield_contrast": float(measurements["brightfield_contrast"]),
                "optical_radius": optical_radius,
                "vertices": circle_vertices(cx, cy, optical_radius),
                "parent_cluster_id": int(parent_label),
                "parent_cluster_size": int(cluster_counts.get(int(parent_label), 1)),
                "detection_source": "brightfield_structure",
            }
        )
        if int(cluster_counts.get(int(parent_label), 1)) > 1:
            multi_cell_cluster_count += 1

    # Strong GFP can obscure the brightfield structure used by the cell
    # detector. Recover any obvious connected GFP patch that was not claimed by
    # a nearby brightfield detection so clearly green cells are not omitted.
    checkpoint("Recovering obvious GFP-positive cells...")
    gfp_seed_count = 0
    strong_labels, strong_label_count = ndi.label(green_pixel_mask)
    for strong_label in range(1, int(strong_label_count) + 1):
        if strong_label % 25 == 0:
            checkpoint("Recovering obvious GFP-positive cells...")
        component = strong_labels == strong_label
        component_pixels = int(np.count_nonzero(component))
        if component_pixels < min_gfp_component_pixels:
            continue
        claimed_fraction = float(
            np.count_nonzero(component & claimed_gfp_mask)
            / max(component_pixels, 1)
        )
        if claimed_fraction >= 0.25:
            continue
        coordinates = np.argwhere(component)
        if not coordinates.size:
            continue
        cy, cx = np.mean(coordinates, axis=0)
        if exclude_border and (
            cy <= typical_radius
            or cx <= typical_radius
            or cy >= height - typical_radius
            or cx >= width - typical_radius
        ):
            continue
        component_values = green_dominance[component]
        gfp_peak = float(np.nanpercentile(component_values, 95.0))
        top_count = max(1, int(np.ceil(component_values.size * 0.10)))
        gfp_top_mean = float(
            np.mean(
                np.partition(component_values, -top_count)[-top_count:]
            )
        )
        required_gfp_pixels = max(
            min_gfp_component_pixels,
            int(np.ceil(min_fraction * typical_area)),
        )
        classification_score = float(
            component_pixels / max(required_gfp_pixels, 1)
        )
        detections.append(
            {
                "classification": "positive",
                "classification_score": max(1.0, classification_score),
                "confidence": float(
                    np.clip(
                        0.65 + 0.20 * max(0.0, classification_score - 1.0),
                        0.0,
                        1.0,
                    )
                ),
                "gfp_fraction": float(component_pixels / max(typical_area, 1.0)),
                "gfp_peak_excess": gfp_peak,
                "gfp_top_mean_excess": gfp_top_mean,
                "gfp_component_pixels": component_pixels,
                "gfp_required_pixels": required_gfp_pixels,
                "gfp_threshold": gfp_threshold,
                "centroid": (float(cx), float(cy)),
                "area": typical_area,
                "equivalent_diameter": float(2.0 * np.sqrt(typical_area / np.pi)),
                "circularity": 1.0,
                "solidity": 1.0,
                "elongation": 1.0,
                "brightfield_contrast": 0.0,
                "optical_radius": typical_radius,
                "vertices": circle_vertices(
                    float(cx),
                    float(cy),
                    typical_radius,
                ),
                "parent_cluster_id": 0,
                "parent_cluster_size": 1,
                "detection_source": "connected_gfp_patch",
            }
        )
        gfp_seed_count += 1
    detections.sort(key=lambda item: (item["centroid"][1], item["centroid"][0]))
    checkpoint("Finishing preview...")
    return detections, {
        "detection_threshold": detection_threshold,
        "gfp_threshold": gfp_threshold,
        "artifact_fraction": float(np.mean(artifact_mask)),
        "accepted_count": len(detections),
        "rejected_count": rejected_count,
        "gfp_seed_count": gfp_seed_count,
        "cells_from_touching_clusters": multi_cell_cluster_count,
        "touching_cluster_count": int(
            sum(1 for count in cluster_counts.values() if int(count) > 1)
        ),
    }


class ImageCanvas(FigureCanvas):
    def __init__(self) -> None:
        self.figure = Figure(figsize=(7.4, 4.0), constrained_layout=False)
        super().__init__(self.figure)
        self.axes = self.figure.add_axes([0.08, 0.14, 0.84, 0.79])
        self.rect_selector: Optional[RectangleSelector] = None
        self.poly_selector: Optional[PolygonSelector] = None
        self.rectangle_callback = None
        self.polygon_callback = None
        self.image_data: Optional[np.ndarray] = None
        self.display_limits: tuple[float, float] = (0.0, 0.0)
        self.image_artist = None
        self.colorbar = None
        self.setMinimumHeight(360)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)

    def show_image(
        self,
        msi_image: MSIImage,
        cmap: str = "viridis",
        log_scale: bool = False,
        display_mode: str = "Physical aspect",
        x_size_mm: float = 1.32,
        y_size_mm: float = 1.01,
        vmin: Optional[float] = None,
        vmax: Optional[float] = None,
        subtitle: str = "",
    ) -> None:
        # Attach the colorbar to the rendered image axes so physical-aspect images
        # do not leave a large unused gap before the scale.
        self.figure.clear()
        # Slightly tighter margins make the MSI itself the visual focus while
        # retaining publication-friendly axes and a dedicated colorbar.
        self.axes = self.figure.add_axes([0.095, 0.12, 0.79, 0.80])

        data = np.asarray(msi_image.data, dtype=float)
        self.image_data = data
        display_data = display_domain_array(data, log_scale)
        finite_display = display_data[np.isfinite(display_data)]
        if finite_display.size:
            display_min = float(np.min(finite_display))
            display_max = float(np.max(finite_display))
        else:
            display_min = display_max = 0.0
        self.display_limits = (display_min, display_max)
        settings = image_display_settings(display_mode, x_size_mm, y_size_mm)
        if display_mode == "Fill panel":
            settings["xlabel"] = ""
            settings["ylabel"] = "Y row"

        im = self.axes.imshow(
            display_data,
            cmap=cmap,
            origin="upper",
            interpolation="nearest",
            aspect=settings["aspect"],
            extent=settings["extent"],
            vmin=vmin,
            vmax=vmax,
        )
        self.image_artist = im
        if settings["box_aspect"] is not None:
            self.axes.set_box_aspect(settings["box_aspect"])

        # Left alignment keeps long m/z/ppm titles over the image rather than
        # extending across the colorbar's scientific-notation multiplier.
        main_title, parsed_subtitle = split_msi_display_title(msi_image.title)
        subtitle = str(subtitle or parsed_subtitle)
        self.axes.set_title(main_title, pad=9, loc="left", fontsize=12, fontweight="semibold")
        if subtitle:
            self.axes.text(
                0.0, 1.015, subtitle, transform=self.axes.transAxes,
                ha="left", va="bottom", fontsize=8.5, alpha=0.72,
            )
        self.axes.set_xlabel(settings["xlabel"], labelpad=3)
        self.axes.set_ylabel(settings["ylabel"], labelpad=3)
        self.axes.tick_params(axis="both", which="major", labelsize=9, length=3)
        divider = make_axes_locatable(self.axes)
        cax = divider.append_axes("right", size="2.5%", pad=0.045)
        colorbar = self.figure.colorbar(im, cax=cax)
        self.colorbar = colorbar
        colorbar.ax.yaxis.get_offset_text().set_horizontalalignment("center")
        colorbar.ax.yaxis.get_offset_text().set_x(0.5)
        self.draw_idle()

    def set_display_clim(self, vmin: float, vmax: float) -> None:
        """Update only the displayed color limits for responsive slider dragging."""
        if self.image_artist is None:
            return
        low = float(vmin)
        high = float(vmax)
        if not np.isfinite(low) or not np.isfinite(high):
            return
        if high <= low:
            high = low + max(abs(low) * 1e-12, 1e-12)
        self.image_artist.set_clim(low, high)
        self.draw_idle()

    def disable_rectangle_selection(self) -> None:
        if self.rect_selector is not None:
            try:
                self.rect_selector.set_active(False)
                self.rect_selector.disconnect_events()
            except Exception:
                pass
            self.rect_selector = None
        if self.poly_selector is not None:
            try:
                self.poly_selector.set_active(False)
                self.poly_selector.disconnect_events()
            except Exception:
                pass
            self.poly_selector = None
        self.rectangle_callback = None
        self.polygon_callback = None
        self.draw_idle()

    def start_polygon_selection(self, callback) -> None:
        """Enable freeform polygon drawing on this canvas."""
        self.disable_rectangle_selection()
        self.polygon_callback = callback
        self.poly_selector = PolygonSelector(self.axes, self._on_polygon_select, useblit=True)
        self.draw_idle()

    def _on_polygon_select(self, vertices) -> None:
        if self.polygon_callback is None or vertices is None or len(vertices) < 3:
            return
        if self.image_data is not None:
            h, w = np.asarray(self.image_data).shape[:2]
            clipped = [(max(0, min(float(x), w - 1)), max(0, min(float(y), h - 1))) for x, y in vertices]
        else:
            clipped = [(float(x), float(y)) for x, y in vertices]
        self.polygon_callback(clipped)
        self.disable_rectangle_selection()

    def _display_data(self, image: np.ndarray, log_scale: bool = False) -> np.ndarray:
        arr = np.asarray(image, dtype=float)
        return np.log1p(np.clip(arr, a_min=0, a_max=None)) if log_scale else arr

    def show_overlay_image(self, base_image: np.ndarray, overlay_image: np.ndarray, title: str, alpha: float = 0.45, cmap: str = "turbo") -> None:
        self.figure.clear()
        self.axes = self.figure.add_axes([0.08, 0.10, 0.88, 0.82])
        base = self._display_data(base_image, log_scale=False)
        if base.ndim == 2:
            self.axes.imshow(base, cmap="gray", origin="upper", interpolation="nearest", aspect="equal")
        else:
            self.axes.imshow(base, origin="upper", interpolation="nearest", aspect="equal")
        ov = np.asarray(overlay_image, dtype=float)
        if np.any(np.isfinite(ov)) and np.nanmax(ov) > np.nanmin(ov):
            show = np.log1p(np.clip(ov, a_min=0, a_max=None))
            self.axes.imshow(show, cmap=cmap, origin="upper", interpolation="nearest", aspect="equal", alpha=float(alpha))
        h, w = np.asarray(base_image).shape[:2]
        self.axes.set_xlim(0, w); self.axes.set_ylim(h, 0)
        self.axes.set_title(title)
        self.axes.set_xlabel("Optical X pixel")
        self.axes.set_ylabel("Optical Y pixel")
        self.draw_idle()

    def start_rectangle_selection(self, callback) -> None:
        self.disable_rectangle_selection()
        self.rectangle_callback = callback
        self.rect_selector = RectangleSelector(
            self.axes,
            self._on_rectangle_select,
            useblit=True,
            button=[1],
            minspanx=2,
            minspany=2,
            spancoords="pixels",
            interactive=True,
        )
        self.draw_idle()

    def _on_rectangle_select(self, eclick, erelease) -> None:
        if self.rectangle_callback is None:
            return
        if eclick.xdata is None or eclick.ydata is None or erelease.xdata is None or erelease.ydata is None:
            return
        self.rectangle_callback(float(eclick.xdata), float(eclick.ydata), float(erelease.xdata), float(erelease.ydata))


class RoiCanvas(FigureCanvas):
    def __init__(self) -> None:
        self.figure = Figure(figsize=(8, 4.8), constrained_layout=False)
        super().__init__(self.figure)
        self.axes = self.figure.add_axes([0.06, 0.12, 0.92, 0.78])
        self.rect_selector: Optional[RectangleSelector] = None
        self.poly_selector: Optional[PolygonSelector] = None
        self.image_data: Optional[np.ndarray] = None
        self.rectangle_callback = None
        self.polygon_callback = None
        self.single_click_callback = None
        self.passive_click_callback = None
        self.click_cid = self.mpl_connect("button_press_event", self._on_single_click)
        self.setMinimumHeight(420)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)

    def show_image(
        self,
        msi_image: MSIImage,
        cmap: str = "viridis",
        log_scale: bool = False,
        vmin: Optional[float] = None,
        vmax: Optional[float] = None,
        title_suffix: str = "ROI drawing surface",
    ) -> None:
        self.figure.clear()
        self.axes = self.figure.add_axes([0.075, 0.12, 0.90, 0.79])
        data = np.asarray(msi_image.data, dtype=float)
        self.image_data = data
        display_data = display_domain_array(data, log_scale)
        self.axes.imshow(
            display_data, cmap=cmap, origin="upper", interpolation="nearest",
            aspect="equal", vmin=vmin, vmax=vmax,
        )
        self.axes.set_xlim(0, display_data.shape[1])
        self.axes.set_ylim(display_data.shape[0], 0)
        main_title, subtitle = split_msi_display_title(msi_image.title)
        self.axes.set_title(main_title, loc="left", fontsize=11, fontweight="semibold", pad=7)
        detail = " • ".join(part for part in [subtitle, title_suffix] if part)
        if detail:
            self.axes.text(0.0, 1.012, detail, transform=self.axes.transAxes, ha="left", va="bottom", fontsize=8, alpha=0.70)
        self.axes.set_xlabel("X pixel / scan")
        self.axes.set_ylabel("Y row / RAW file")
        self.axes.tick_params(axis="both", labelsize=8.5, length=3)
        self._restore_current_view()
        self.draw_idle()

    def show_optical_reference(
        self,
        optical_image: np.ndarray,
        coordinate_shape: tuple[int, int],
        title: str = "Optional optical ROI reference",
    ) -> None:
        """Show an optical photo in the active MSI pixel coordinate system.

        The optical photo is a drawing aid only. Its displayed extent is mapped
        onto the current MSI view so every ROI created here still produces a
        mask with the correct MSI dimensions for feature extraction.
        """
        self.figure.clear()
        self.axes = self.figure.add_axes([0.06, 0.12, 0.92, 0.78])
        height, width = tuple(int(v) for v in coordinate_shape[:2])
        self.image_data = np.zeros((height, width), dtype=float)
        optical = np.asarray(optical_image)
        if optical.ndim == 2:
            self.axes.imshow(
                optical,
                cmap="gray",
                origin="upper",
                interpolation="nearest",
                aspect="equal",
                extent=(0, width, height, 0),
            )
        else:
            self.axes.imshow(
                optical[..., :3],
                origin="upper",
                interpolation="nearest",
                aspect="equal",
                extent=(0, width, height, 0),
            )
        self.axes.set_xlim(0, width)
        self.axes.set_ylim(height, 0)
        self.axes.set_title(title + " — mapped to MSI pixel coordinates")
        self.axes.set_xlabel("X pixel / scan")
        self.axes.set_ylabel("Y row / RAW file")
        self.axes.set_aspect("equal", adjustable="box")
        self.axes.tick_params(axis="both", labelsize=8.5, length=3)
        self.draw_idle()

    def show_placeholder(self, title: str, message: str) -> None:
        """Show a clean empty reference panel without creating an interactive ROI surface."""
        self.figure.clear()
        self.axes = self.figure.add_axes([0.06, 0.10, 0.90, 0.82])
        self.image_data = None
        self.axes.set_title(str(title), loc="left", fontsize=11, fontweight="semibold")
        self.axes.text(0.5, 0.5, str(message), ha="center", va="center", transform=self.axes.transAxes, fontsize=10, alpha=0.70, wrap=True)
        self.axes.set_axis_off()
        self.draw_idle()

    def disable_tools(self) -> None:
        self.single_click_callback = None
        if self.rect_selector is not None:
            self.rect_selector.set_active(False)
            self.rect_selector.disconnect_events()
            self.rect_selector = None
        if self.poly_selector is not None:
            self.poly_selector.set_active(False)
            self.poly_selector.disconnect_events()
            self.poly_selector = None
        self.draw_idle()

    def _restore_current_view(self) -> None:
        if self.image_data is None or self.axes is None:
            return
        h, w = self.image_data.shape
        self.axes.set_xlim(0, w)
        self.axes.set_ylim(h, 0)
        self.axes.set_aspect("equal", adjustable="box")

    def enable_rectangle_drawing(self, callback) -> None:
        self.disable_tools()
        self.rectangle_callback = callback
        self._restore_current_view()
        self.rect_selector = RectangleSelector(
            self.axes,
            self._on_rectangle_select,
            useblit=True,
            button=[1],
            minspanx=2,
            minspany=2,
            spancoords="pixels",
            interactive=True,
        )
        self._restore_current_view()
        self.draw_idle()

    def enable_polygon_drawing(self, callback) -> None:
        self.disable_tools()
        self.polygon_callback = callback
        self._restore_current_view()
        self.poly_selector = PolygonSelector(self.axes, self._on_polygon_select, useblit=True)
        self._restore_current_view()
        self.draw_idle()

    def _on_rectangle_select(self, eclick, erelease) -> None:
        if self.image_data is None or self.rectangle_callback is None:
            return
        if eclick.xdata is None or eclick.ydata is None or erelease.xdata is None or erelease.ydata is None:
            return
        x1, y1 = int(round(eclick.xdata)), int(round(eclick.ydata))
        x2, y2 = int(round(erelease.xdata)), int(round(erelease.ydata))
        x_min, x_max = sorted([x1, x2])
        y_min, y_max = sorted([y1, y2])
        height, width = self.image_data.shape
        x_min = max(0, min(x_min, width - 1))
        x_max = max(0, min(x_max, width - 1))
        y_min = max(0, min(y_min, height - 1))
        y_max = max(0, min(y_max, height - 1))
        if x_max <= x_min or y_max <= y_min:
            return
        self.rectangle_callback(x_min, y_min, x_max, y_max)

    def enable_single_click(self, callback) -> None:
        self.disable_tools()
        self.single_click_callback = callback
        self.draw_idle()

    def set_passive_click_callback(self, callback) -> None:
        """Keep image-based ROI selection available when no drawing tool is active."""
        self.passive_click_callback = callback

    def _on_single_click(self, event) -> None:
        if event.inaxes != self.axes or event.xdata is None or event.ydata is None:
            return
        if self.single_click_callback is not None:
            self.single_click_callback(float(event.xdata), float(event.ydata))
            return
        if self.rect_selector is None and self.poly_selector is None and self.passive_click_callback is not None:
            self.passive_click_callback(float(event.xdata), float(event.ydata))

    def _on_polygon_select(self, vertices) -> None:
        if self.image_data is None or self.polygon_callback is None:
            return
        if vertices is None or len(vertices) < 3:
            return
        height, width = self.image_data.shape
        clipped = []
        for x, y in vertices:
            clipped.append((max(0, min(float(x), width - 1)), max(0, min(float(y), height - 1))))
        self.polygon_callback(clipped)
        self.disable_tools()

    def add_rectangle_patch(self, x_min: int, y_min: int, x_max: int, y_max: int, color=None, linewidth: float = 2.0, linestyle: str = "-") -> None:
        self.axes.add_patch(Rectangle((x_min, y_min), x_max - x_min, y_max - y_min, fill=False, linewidth=linewidth, edgecolor=color, linestyle=linestyle))
        self.draw_idle()

    def add_polygon_patch(self, vertices: list[tuple[float, float]], color=None, linewidth: float = 2.0, linestyle: str = "-") -> None:
        self.axes.add_patch(Polygon(vertices, closed=True, fill=False, linewidth=linewidth, edgecolor=color, linestyle=linestyle))
        self.draw_idle()

    def add_circle_patch(self, x: float, y: float, radius: float) -> None:
        self.axes.add_patch(Ellipse((float(x), float(y)), width=2*float(radius), height=2*float(radius), fill=False, linewidth=2))
        self.axes.plot(float(x), float(y), marker="+", markersize=7)
        self.draw_idle()

    def add_ellipse_patch(self, x: float, y: float, rx: float, ry: float, color=None, linewidth: float = 2.0, linestyle: str = "-") -> None:
        self.axes.add_patch(Ellipse((float(x), float(y)), width=2*float(rx), height=2*float(ry), fill=False, linewidth=linewidth, edgecolor=color, linestyle=linestyle))
        self.axes.plot(float(x), float(y), marker="+", markersize=7, color=color)
        self.draw_idle()

    def add_mask_overlay(self, mask: np.ndarray, overlay_index: int = 0, alpha: float = 0.38) -> None:
        """Display an ROI mask as a translucent pixel overlay.

        This is better than drawing thousands of contour outlines for aggregate
        cluster ROIs, especially when a chemical cluster contains many small,
        disconnected pixel regions. The stored mask remains the authoritative
        ROI geometry used for feature extraction/statistics.
        """
        if self.axes is None or mask is None:
            return
        mask = np.asarray(mask, dtype=bool)
        if mask.ndim != 2 or not np.any(mask):
            return
        cmap = colormaps.get_cmap("tab20")
        color = cmap(int(overlay_index) % 20)
        rgba = np.zeros((mask.shape[0], mask.shape[1], 4), dtype=float)
        rgba[mask, 0] = color[0]
        rgba[mask, 1] = color[1]
        rgba[mask, 2] = color[2]
        rgba[mask, 3] = float(alpha)
        self.axes.imshow(rgba, origin="upper", interpolation="nearest", aspect="equal")
        self.draw_idle()




def connect_single_click(button: QPushButton, callback, status_label: Optional[QLabel] = None, running_text: str = "Running...") -> None:
    """Connect a button to a callback while preventing repeated queued clicks.

    This is intentionally lightweight. It disables the clicked button while the operation runs
    so users cannot accidentally queue the same long operation multiple times when the UI pauses.
    """
    def wrapped(*_args):
        if bool(button.property("_msi_busy")):
            return
        original_text = button.text()
        button.setProperty("_msi_busy", True)
        button.setEnabled(False)
        button.setText(running_text)
        if status_label is not None:
            status_label.setText(f"{original_text} is running... please wait.")
        QApplication.processEvents()
        try:
            callback()
        except Exception:
            raise
        finally:
            button.setText(original_text)
            button.setEnabled(True)
            button.setProperty("_msi_busy", False)
            if status_label is not None and "is running... please wait" in status_label.text():
                status_label.setText("Ready.")
            QApplication.processEvents()
    button.clicked.connect(wrapped)


class PixelSizeDialog(QDialog):
    """Pop-out calculator for reporting physical MSI pixel size without changing display aspect settings."""

    def __init__(self, parent_tab: "ThermoPipelineTab") -> None:
        super().__init__(parent_tab)
        self.parent_tab = parent_tab
        self.setWindowTitle("Calculate Pixel Size")
        self.setMinimumWidth(560)
        layout = QVBoxLayout(self)

        intro = QLabel(
            "Estimate physical MSI pixel dimensions from stage velocity, MS scan timing, and stage step size. "
            "Use Apply to Image Display to set the first-tab X/Y physical size and switch the viewer to Physical aspect."
        )
        intro.setWordWrap(True)
        layout.addWidget(intro)

        form = QFormLayout()
        self.stage_velocity = QDoubleSpinBox(); self.stage_velocity.setRange(0.000001, 1000); self.stage_velocity.setDecimals(6); self.stage_velocity.setValue(0.010000); self.stage_velocity.setSuffix(" mm/s")
        self.avg_scan_time = QDoubleSpinBox(); self.avg_scan_time.setRange(0.0, 1000); self.avg_scan_time.setDecimals(6); self.avg_scan_time.setValue(0.271000); self.avg_scan_time.setSuffix(" s/scan")
        self.line_time = QDoubleSpinBox(); self.line_time.setRange(0.0, 100000); self.line_time.setDecimals(4); self.line_time.setValue(0.0); self.line_time.setSuffix(" s")
        self.line_time_min = QDoubleSpinBox(); self.line_time_min.setRange(0.0, 100000); self.line_time_min.setDecimals(4); self.line_time_min.setValue(0.0); self.line_time_min.setSuffix(" min")
        self.scans_per_line = QDoubleSpinBox(); self.scans_per_line.setRange(1, 1000000); self.scans_per_line.setDecimals(1)
        self.y_step_um = QDoubleSpinBox(); self.y_step_um.setRange(0.001, 100000); self.y_step_um.setDecimals(3); self.y_step_um.setValue(10.000); self.y_step_um.setSuffix(" µm")
        self.x_pixels = QSpinBox(); self.x_pixels.setRange(1, 1000000)
        self.y_rows = QSpinBox(); self.y_rows.setRange(1, 1000000)

        current = parent_tab.shared_state.current_image
        if current is not None:
            h, w = current.data.shape[:2]
        else:
            h = int(parent_tab.end_scan.value()) if hasattr(parent_tab, 'end_scan') else 1
            w = max(1, int(parent_tab.end_scan.value()) - int(parent_tab.start_scan.value()) + 1) if hasattr(parent_tab, 'end_scan') else 1
        self.x_pixels.setValue(int(w))
        self.y_rows.setValue(int(h))
        self.scans_per_line.setValue(float(w))

        form.addRow("Stage velocity:", self.stage_velocity)
        form.addRow("Average scan time:", self.avg_scan_time)
        form.addRow("Line/movement time, optional:", self.line_time)
        form.addRow("Line/movement time in minutes:", self.line_time_min)
        form.addRow("Scans per line:", self.scans_per_line)
        form.addRow("Y step size:", self.y_step_um)
        form.addRow("X pixels/scans:", self.x_pixels)
        form.addRow("Y rows:", self.y_rows)
        layout.addLayout(form)

        help_text = QLabel(
            "Equations: X pixel size = stage velocity × average scan time. "
            "If movement time is entered in seconds or minutes, average scan time = movement time / scans per line. "
            "Y pixel size = stage step size. Use 'Estimate scans from mzML' to count spectra from up to 10 mzML rows."
        )
        help_text.setWordWrap(True)
        layout.addWidget(help_text)

        self.result_label = QLabel("No calculation yet.")
        self.result_label.setWordWrap(True)
        self.result_label.setStyleSheet("font-weight: 600;")
        layout.addWidget(self.result_label)

        row = QHBoxLayout()
        self.calculate_button = QPushButton("Calculate")
        self.estimate_button = QPushButton("Estimate scans from mzML")
        self.apply_button = QPushButton("Apply to Image Display")
        self.close_button = QPushButton("Close")
        row.addWidget(self.calculate_button)
        row.addWidget(self.estimate_button)
        row.addWidget(self.apply_button)
        row.addWidget(self.close_button)
        row.addStretch()
        layout.addLayout(row)

        self.x_length_mm = 0.0
        self.y_length_mm = 0.0
        self.calculate_button.clicked.connect(self.calculate)
        self.estimate_button.clicked.connect(self.estimate_scans_from_mzml)
        self.apply_button.clicked.connect(self.apply_to_display)
        self.close_button.clicked.connect(self.accept)
        self.calculate()

    def calculate(self) -> None:
        velocity = float(self.stage_velocity.value())
        avg_time = float(self.avg_scan_time.value())
        line_time_seconds = float(self.line_time.value())
        line_time_minutes = float(self.line_time_min.value())
        scans = max(float(self.scans_per_line.value()), 1.0)
        if line_time_minutes > 0:
            avg_time = (line_time_minutes * 60.0) / scans
        elif line_time_seconds > 0:
            avg_time = line_time_seconds / scans
        x_pixel_mm = velocity * avg_time
        y_pixel_mm = float(self.y_step_um.value()) / 1000.0
        self.x_length_mm = x_pixel_mm * int(self.x_pixels.value())
        self.y_length_mm = y_pixel_mm * int(self.y_rows.value())
        self.result_label.setText(
            f"X pixel = {x_pixel_mm*1000:.3f} µm | Y pixel = {y_pixel_mm*1000:.3f} µm\n"
            f"X length = {self.x_length_mm:.4f} mm | Y length = {self.y_length_mm:.4f} mm\n"
            "Click Apply to Image Display to use these values for Physical aspect display."
        )

    def apply_to_display(self) -> None:
        self.calculate()
        self.parent_tab.x_size_mm.setValue(max(self.x_length_mm, 0.001))
        self.parent_tab.y_size_mm.setValue(max(self.y_length_mm, 0.001))
        self.parent_tab.display_mode_box.setCurrentText("Physical aspect")
        self.parent_tab.redraw_current()
        self.parent_tab.status_label.setText(
            f"Applied physical image size: X={self.x_length_mm:.4f} mm, Y={self.y_length_mm:.4f} mm."
        )

    def estimate_scans_from_mzml(self) -> None:
        folder = self.parent_tab.get_mzml_folder()
        if folder is None or not Path(folder).exists():
            QMessageBox.warning(self, "No mzML folder", "Select or create an mzML output folder first.")
            return
        mzml_files = find_mzml_files(Path(folder))[:10]
        if not mzml_files:
            QMessageBox.warning(self, "No mzML files", "No mzML files were found in the current mzML/output folder.")
            return
        counts = []
        for mzml_path in mzml_files:
            try:
                reader = pymzml.run.Reader(str(mzml_path))
                counts.append(sum(1 for _ in reader))
            except Exception:
                continue
        if not counts:
            QMessageBox.warning(self, "Scan estimate failed", "Could not count spectra in the sampled mzML files.")
            return
        avg_count = float(np.mean(counts))
        self.scans_per_line.setValue(avg_count)
        self.x_pixels.setValue(max(1, int(round(avg_count))))
        self.result_label.setText(
            f"Estimated scans per line from {len(counts)} mzML files: {avg_count:.1f}\n"
            f"Counts sampled: {', '.join(str(int(c)) for c in counts)}"
        )
        self.calculate()


class SimilarImagesDialog(QDialog):
    """Table + image preview for ion-image similarity search results."""

    def __init__(self, parent_tab: "ThermoPipelineTab", results_df: pd.DataFrame) -> None:
        super().__init__(parent_tab)
        self.parent_tab = parent_tab
        self.results_df = results_df.copy()
        self.setWindowTitle("Similar MSI Images")
        self.resize(1100, 720)

        layout = QVBoxLayout(self)
        intro = QLabel(
            "Images are ranked by Pearson R similarity to the query image. "
            "High positive R means similar spatial intensity pattern; negative R means an opposite pattern. "
            "Double-click or select a row to preview that m/z image."
        )
        intro.setWordWrap(True)
        layout.addWidget(intro)

        main_row = QHBoxLayout()
        self.table = QTableWidget()
        self.table.setSelectionBehavior(QTableWidget.SelectRows)
        self.table.setMinimumWidth(520)
        main_row.addWidget(self.table, stretch=1)

        right_col = QVBoxLayout()
        self.preview_canvas = ImageCanvas()
        self.preview_canvas.setMinimumHeight(520)
        right_col.addWidget(self.preview_canvas, stretch=1)
        self.preview_label = QLabel("Select a row to preview an MSI image.")
        self.preview_label.setWordWrap(True)
        right_col.addWidget(self.preview_label)
        main_row.addLayout(right_col, stretch=1)

        layout.addLayout(main_row, stretch=1)

        bottom = QHBoxLayout()
        self.export_button = QPushButton("Export Similarity CSV")
        self.load_button = QPushButton("Load Selected as Current Image")
        self.close_button = QPushButton("Close")
        bottom.addWidget(self.export_button)
        bottom.addWidget(self.load_button)
        bottom.addStretch()
        bottom.addWidget(self.close_button)
        layout.addLayout(bottom)

        self.populate_table()
        self.table.cellClicked.connect(self.preview_row)
        self.table.cellDoubleClicked.connect(self.preview_row)
        self.export_button.clicked.connect(self.export_csv)
        self.load_button.clicked.connect(self.load_selected_as_current)
        self.close_button.clicked.connect(self.accept)

        if len(self.results_df):
            self.table.selectRow(0)
            self.preview_row(0, 0)

    def populate_table(self) -> None:
        display_cols = ["rank", "m/z", "pearson_r", "cosine_similarity", "ssd_normalized", "cached", "source"]
        cols = [c for c in display_cols if c in self.results_df.columns]
        self.table.clear()
        self.table.setRowCount(len(self.results_df))
        self.table.setColumnCount(len(cols))
        self.table.setHorizontalHeaderLabels(cols)
        for r, (_, row) in enumerate(self.results_df.iterrows()):
            for c, col in enumerate(cols):
                val = row.get(col, "")
                if isinstance(val, float):
                    text = f"{val:.6g}"
                else:
                    text = str(val)
                self.table.setItem(r, c, QTableWidgetItem(text))
        self.table.resizeColumnsToContents()

    def selected_row_index(self) -> Optional[int]:
        rows = sorted({idx.row() for idx in self.table.selectedIndexes()})
        if not rows:
            return None
        return int(rows[0])

    def preview_row(self, row: int, _column: int = 0) -> None:
        if row < 0 or row >= len(self.results_df):
            return
        rec = self.results_df.iloc[row]
        try:
            mz = float(rec["m/z"])
            image = self.parent_tab.load_or_build_ion_image(mz)
            display_img = MSIImage(apply_crop_to_array(image, self.parent_tab.shared_state.msi_crop_rect), f"Similar m/z {mz:.5f} | R={float(rec.get('pearson_r', np.nan)):.3f}")
            self.preview_canvas.show_image(
                display_img,
                cmap=self.parent_tab.cmap_box.currentText(),
                log_scale=self.parent_tab.log_button.isChecked(),
                display_mode="Pixel equal",
                x_size_mm=self.parent_tab.x_size_mm.value(),
                y_size_mm=self.parent_tab.y_size_mm.value(),
            )
            self.preview_label.setText(
                f"m/z {mz:.5f} | Pearson R={float(rec.get('pearson_r', np.nan)):.4f} | "
                f"Cosine={float(rec.get('cosine_similarity', np.nan)):.4f}"
            )
        except Exception as exc:
            self.preview_label.setText(f"Preview failed: {exc}")

    def load_selected_as_current(self) -> None:
        row = self.selected_row_index()
        if row is None:
            return
        rec = self.results_df.iloc[row]
        mz = float(rec["m/z"])
        try:
            image = self.parent_tab.load_or_build_ion_image(mz)
            self.parent_tab.target_mz.setValue(mz)
            self.parent_tab.set_current_image_from_full(image, f"Ion Image m/z {mz:.5f}", image_kind="ion")
            self.parent_tab.status_label.setText(f"Loaded similar m/z {mz:.5f} as current image.")
        except Exception as exc:
            QMessageBox.warning(self, "Load image failed", str(exc))

    def export_csv(self) -> None:
        file_path, _ = QFileDialog.getSaveFileName(self, "Export image similarity results", "similar_msi_images.csv", "CSV files (*.csv);;All files (*.*)")
        if not file_path:
            return
        self.results_df.to_csv(file_path, index=False)
        self.parent_tab.status_label.setText(f"Similarity table exported: {file_path}")


class ImageCleanupDialog(QDialog):
    """Optional visual/analysis cleanup for the current MSI image."""

    def __init__(self, parent_tab: "ThermoPipelineTab") -> None:
        super().__init__(parent_tab)
        self.parent_tab = parent_tab
        self.setWindowTitle("Clean / Denoise Current MSI Image")
        self.resize(1200, 760)

        source = parent_tab.get_cleanup_source_image()
        if source is None:
            raise ValueError("No current MSI image is available.")
        self.original = np.asarray(source, dtype=float)
        self.cleaned = self.original.copy()

        layout = QVBoxLayout(self)
        info = QLabel(
            "Use this as an optional cleanup/visualization tool for fuzzy MSI images. "
            "Start with mild smoothing or stripe correction. Applying cleanup changes the current displayed image; "
            "use Reset Current Image to reload the original cached/raw image."
        )
        info.setWordWrap(True)
        layout.addWidget(info)

        controls = QHBoxLayout()
        self.method_box = QComboBox()
        self.method_box.addItems([
            "Gaussian smooth",
            "Median despeckle",
            "Horizontal stripe correction",
            "Vertical stripe correction",
            "Background subtract",
            "Gaussian + horizontal stripe correction",
            "Median + horizontal stripe correction",
        ])
        self.sigma_spin = QDoubleSpinBox()
        self.sigma_spin.setRange(0.1, 20.0)
        self.sigma_spin.setDecimals(2)
        self.sigma_spin.setValue(1.0)
        self.sigma_spin.setToolTip("Gaussian smoothing/background scale. Use 0.5–1.5 for mild denoising; larger values can blur real cell/tissue structure.")
        self.median_size_spin = QSpinBox()
        self.median_size_spin.setRange(1, 25)
        self.median_size_spin.setValue(3)
        self.median_size_spin.setToolTip("Median filter window size in pixels. Odd values like 3 or 5 are usually safest.")
        self.stripe_strength_spin = QDoubleSpinBox()
        self.stripe_strength_spin.setRange(0.0, 1.0)
        self.stripe_strength_spin.setDecimals(2)
        self.stripe_strength_spin.setValue(1.0)
        self.stripe_strength_spin.setToolTip("How strongly row/column median offsets are removed. 1.0 fully removes the estimated stripe offset.")
        self.clip_zero_box = QCheckBox("Clip negative to zero")
        self.clip_zero_box.setChecked(True)
        self.preview_button = QPushButton("Preview")
        self.apply_button = QPushButton("Apply to Current Image")
        self.apply_all_button = QPushButton("Apply to All Cached")
        self.reset_button = QPushButton("Reset Current Image")
        self.close_button = QPushButton("Close")

        for widget in [
            QLabel("Method:"), self.method_box,
            QLabel("σ:"), self.sigma_spin,
            QLabel("Median px:"), self.median_size_spin,
            QLabel("Stripe strength:"), self.stripe_strength_spin,
            self.clip_zero_box,
            self.preview_button, self.apply_button, self.apply_all_button, self.reset_button, self.close_button,
        ]:
            controls.addWidget(widget)
        controls.addStretch()
        layout.addLayout(controls)

        viewer_row = QHBoxLayout()
        left_col = QVBoxLayout()
        left_col.addWidget(QLabel("Original/current image"))
        self.original_canvas = ImageCanvas()
        left_col.addWidget(self.original_canvas, stretch=1)
        right_col = QVBoxLayout()
        right_col.addWidget(QLabel("Cleaned preview"))
        self.cleaned_canvas = ImageCanvas()
        right_col.addWidget(self.cleaned_canvas, stretch=1)
        viewer_row.addLayout(left_col, stretch=1)
        viewer_row.addLayout(right_col, stretch=1)
        layout.addLayout(viewer_row, stretch=1)

        self.status = QLabel("")
        self.status.setWordWrap(True)
        layout.addWidget(self.status)

        self.preview_button.clicked.connect(self.preview)
        self.apply_button.clicked.connect(self.apply)
        self.apply_all_button.clicked.connect(self.apply_to_all_cached)
        self.reset_button.clicked.connect(self.reset_current)
        self.close_button.clicked.connect(self.accept)

        self.show_original()
        self.preview()

    def show_original(self) -> None:
        self.original_canvas.show_image(
            MSIImage(self.original, "Original/current MSI image"),
            cmap=self.parent_tab.cmap_box.currentText(),
            log_scale=self.parent_tab.log_button.isChecked(),
            display_mode=self.parent_tab.display_mode_box.currentText(),
            x_size_mm=self.parent_tab.x_size_mm.value(),
            y_size_mm=self.parent_tab.y_size_mm.value(),
        )

    def clean_image(self, image: np.ndarray) -> np.ndarray:
        arr = np.asarray(image, dtype=float).copy()
        method = self.method_box.currentText()
        sigma = float(self.sigma_spin.value())
        med_size = int(self.median_size_spin.value())
        if med_size % 2 == 0:
            med_size += 1
        strength = float(self.stripe_strength_spin.value())

        def gaussian(a):
            return ndi.gaussian_filter(a, sigma=sigma)

        def median(a):
            return ndi.median_filter(a, size=med_size)

        def horizontal(a):
            row_med = np.nanmedian(a, axis=1)
            global_med = np.nanmedian(a)
            offset = (row_med - global_med)[:, None]
            return a - strength * offset

        def vertical(a):
            col_med = np.nanmedian(a, axis=0)
            global_med = np.nanmedian(a)
            offset = (col_med - global_med)[None, :]
            return a - strength * offset

        def bg_subtract(a):
            bg = ndi.gaussian_filter(a, sigma=max(sigma, 0.1))
            out = a - bg
            out += np.nanmedian(bg)
            return out

        if method == "Gaussian smooth":
            arr = gaussian(arr)
        elif method == "Median despeckle":
            arr = median(arr)
        elif method == "Horizontal stripe correction":
            arr = horizontal(arr)
        elif method == "Vertical stripe correction":
            arr = vertical(arr)
        elif method == "Background subtract":
            arr = bg_subtract(arr)
        elif method == "Gaussian + horizontal stripe correction":
            arr = horizontal(gaussian(arr))
        elif method == "Median + horizontal stripe correction":
            arr = horizontal(median(arr))

        if self.clip_zero_box.isChecked():
            arr = np.clip(arr, a_min=0, a_max=None)
        return arr

    def preview(self) -> None:
        try:
            self.cleaned = self.clean_image(self.original)
            self.cleaned_canvas.show_image(
                MSIImage(self.cleaned, f"Cleaned preview: {self.method_box.currentText()}"),
                cmap=self.parent_tab.cmap_box.currentText(),
                log_scale=self.parent_tab.log_button.isChecked(),
                display_mode="Pixel equal",
                x_size_mm=self.parent_tab.x_size_mm.value(),
                y_size_mm=self.parent_tab.y_size_mm.value(),
            )
            orig_sd = float(np.nanstd(self.original))
            clean_sd = float(np.nanstd(self.cleaned))
            self.status.setText(
                f"Preview complete. Original SD={orig_sd:.4g}; cleaned SD={clean_sd:.4g}. "
                "Use mild settings first; over-smoothing can erase real single-cell structure."
            )
        except Exception as exc:
            QMessageBox.warning(self, "Cleanup preview failed", str(exc))

    def apply(self) -> None:
        try:
            self.preview()
            self.parent_tab.apply_cleaned_image(self.cleaned, self.method_box.currentText())
            self.status.setText("Applied cleanup to the current MSI image.")
        except Exception as exc:
            QMessageBox.warning(self, "Apply cleanup failed", str(exc))

    def apply_to_all_cached(self) -> None:
        try:
            self.parent_tab.apply_correction_to_all_cached(
                self.method_box.currentText(),
                float(self.sigma_spin.value()),
                int(self.median_size_spin.value()),
                float(self.stripe_strength_spin.value()),
                bool(self.clip_zero_box.isChecked()),
            )
            self.status.setText("Applied correction to all cached feature-table ion images and switched to corrected cache mode.")
        except Exception as exc:
            QMessageBox.warning(self, "Batch correction failed", str(exc))

    def reset_current(self) -> None:
        try:
            self.parent_tab.reset_current_image_processing()
            self.original = np.asarray(self.parent_tab.get_cleanup_source_image(), dtype=float)
            self.show_original()
            self.preview()
            self.status.setText("Reset current image from cached/raw source.")
        except Exception as exc:
            QMessageBox.warning(self, "Reset failed", str(exc))


