        self.nudge_right_button.clicked.connect(lambda: self.nudge_alignment(self.nudge_step_spin.value(), 0.0))
        self.nudge_up_button.clicked.connect(lambda: self.nudge_alignment(0.0, -self.nudge_step_spin.value()))
        self.nudge_down_button.clicked.connect(lambda: self.nudge_alignment(0.0, self.nudge_step_spin.value()))
