class CartographyWorker(QThread):
    """Background worker for the heavy Spatial Molecular Cartography model fit.

    The GUI owns data loading, preprocessing, domain calling, tables, and drawing.
    This worker owns the expensive W/H factorization/refinement step so large MSI
    datasets are less likely to make the Qt window appear frozen. It is designed
    as a practical MSI Analysis Studio optimizer, not a direct FICTURE/TRIFASE
    implementation.
    """

    status = Signal(str)
    finished_ok = Signal(dict)
    failed = Signal(str)

    def __init__(self, X: np.ndarray, valid_mask: np.ndarray, n_factors: int, settings: dict, parent=None) -> None:
        super().__init__(parent)
        self.X = np.asarray(X, dtype=float)
        self.valid_mask = np.asarray(valid_mask, dtype=bool) if valid_mask is not None else None
        self.n_factors = int(n_factors)
        self.settings = dict(settings)
        self._cancel_requested = False

    def cancel(self) -> None:
        self._cancel_requested = True

    def _status(self, text: str) -> None:
        self.status.emit(text)

    def _check_cancel(self) -> None:
        if self._cancel_requested:
            raise RuntimeError("Spatial Molecular Cartography was cancelled.")

    def run(self) -> None:
        try:
            if NMF is None:
                raise RuntimeError("scikit-learn is required. Install with: pip install scikit-learn")
            X = np.nan_to_num(np.clip(self.X, a_min=0.0, a_max=None), nan=0.0, posinf=0.0, neginf=0.0)
            max_possible = min(X.shape[0], X.shape[1])
            n_factors = max(2, min(int(self.n_factors), int(max_possible)))
            if n_factors < 2:
                raise ValueError("Need at least two valid pixels and two m/z features after preprocessing.")

            self._status("Running initial molecular factorization in background...")
            model = NMF(
                n_components=n_factors,
                init="nndsvda",
                max_iter=int(self.settings.get("max_iter", 500)),
                random_state=int(self.settings.get("random_seed", 0)),
            )
            W = np.clip(model.fit_transform(X), a_min=0.0, a_max=None)
            H = np.clip(model.components_, a_min=0.0, a_max=None)
            initial_error = self.reconstruction_error(X, W, H)
            edges = self.build_spatial_edges(self.valid_mask, self.settings.get("neighbor_type", "4-neighbor"))
            initial_smoothness = self.spatial_smoothness_score(W, edges)

            mode = self.settings.get("mode", "Basic NMF Cartography")
            optimizer_requested = self.settings.get("optimizer", "Graph-Laplacian NMF updates")
            optimizer_used = "Basic NMF only"
            error_history = []
            smoothness_history = []

            if mode in {"Spatially Regularized Cartography", "Spatial Co-Clustering / m/z Module Cartography"}:
                self._status("Running spatially regularized background refinement...")
                if edges is None or len(edges) == 0 or int(self.settings.get("refinement_iterations", 0)) <= 0:
                    optimizer_used = "No spatial refinement (no graph/iterations)"
                else:
                    try:
                        if optimizer_requested == "Graph-Laplacian NMF updates":
                            W, H, error_history, smoothness_history = self.graph_laplacian_nmf_refinement(X, W, H, edges)
                            optimizer_used = "Graph-Laplacian NMF updates"
                        else:
                            W, H, error_history, smoothness_history = self.smooth_refit_spatial_refinement(X, W, H, edges)
                            optimizer_used = "Smooth/refit fallback"
                    except Exception as exc:
                        # Keep the basic result instead of crashing the whole tab.
                        optimizer_used = f"Advanced optimizer failed; Basic NMF fallback used ({exc})"
                        error_history = []
                        smoothness_history = []

            final_error = self.reconstruction_error(X, W, H)
            final_smoothness = self.spatial_smoothness_score(W, edges)
            self.finished_ok.emit({
                "W": np.clip(W, a_min=0.0, a_max=None),
                "H": np.clip(H, a_min=0.0, a_max=None),
                "edges": edges,
                "mode": mode,
                "optimizer_used": optimizer_used,
                "initial_error": float(initial_error),
                "final_error": float(final_error),
                "initial_smoothness": float(initial_smoothness) if np.isfinite(initial_smoothness) else np.nan,
                "final_smoothness": float(final_smoothness) if np.isfinite(final_smoothness) else np.nan,
                "error_history": [float(x) for x in error_history],
                "smoothness_history": [float(x) if np.isfinite(x) else np.nan for x in smoothness_history],
            })
        except Exception as exc:
            self.failed.emit(str(exc))

    def graph_laplacian_nmf_refinement(self, X: np.ndarray, W: np.ndarray, H: np.ndarray, edges: np.ndarray):
        eps = 1e-12
        lam = max(0.0, float(self.settings.get("spatial_lambda", 1.0)))
        iterations = int(self.settings.get("refinement_iterations", 5))
        a = edges[:, 0].astype(int)
        b = edges[:, 1].astype(int)
        degree = np.zeros(W.shape[0], dtype=float)
        np.add.at(degree, a, 1.0)
        np.add.at(degree, b, 1.0)
        error_history = []
        smoothness_history = []
        for i in range(iterations):
            self._check_cancel()
            self._status(f"Graph-Laplacian refinement {i + 1}/{iterations}: updating m/z loadings H...")
            numerator_h = W.T @ X
            denominator_h = (W.T @ W @ H) + eps
            H = H * (numerator_h / denominator_h)
            H = np.clip(H, a_min=eps, a_max=None)

            self._status(f"Graph-Laplacian refinement {i + 1}/{iterations}: updating spatial factors W...")
            AW = np.zeros_like(W, dtype=float)
            np.add.at(AW, a, W[b])
            np.add.at(AW, b, W[a])
            numerator_w = (X @ H.T) + (lam * AW)
            denominator_w = (W @ (H @ H.T)) + (lam * degree[:, None] * W) + eps
            W = W * (numerator_w / denominator_w)
            W = np.clip(W, a_min=eps, a_max=None)
            W, H = self.normalize_factor_scales(W, H)
            err = self.reconstruction_error(X, W, H)
            smooth = self.spatial_smoothness_score(W, edges)
            error_history.append(err)
            smoothness_history.append(smooth)
            self._status(f"Graph-Laplacian refinement {i + 1}/{iterations}: error={err:.4g}, smoothness={smooth:.4g}")
        return W, H, error_history, smoothness_history

    def smooth_refit_spatial_refinement(self, X: np.ndarray, W: np.ndarray, H: np.ndarray, edges: np.ndarray):
        iterations = int(self.settings.get("refinement_iterations", 5))
        lam = float(self.settings.get("spatial_lambda", 1.0))
        error_history = []
        smoothness_history = []
        for i in range(iterations):
            self._check_cancel()
            self._status(f"Spatial fallback refinement {i + 1}/{iterations}: smoothing W and refitting H/W...")
            W = self.smooth_W_by_graph(W, edges, lam)
            H = self.refit_H_given_W(X, W)
            W = self.refit_W_given_H(X, H)
            W = self.smooth_W_by_graph(W, edges, lam * 0.5)
            W, H = self.normalize_factor_scales(W, H)
            error_history.append(self.reconstruction_error(X, W, H))
            smoothness_history.append(self.spatial_smoothness_score(W, edges))
        return W, H, error_history, smoothness_history

    @staticmethod
    def refit_H_given_W(X: np.ndarray, W: np.ndarray) -> np.ndarray:
        try:
            H = np.linalg.lstsq(W + 1e-12, X, rcond=None)[0]
        except Exception:
            H = np.linalg.pinv(W + 1e-12) @ X
        return np.clip(H, a_min=0.0, a_max=None)

    @staticmethod
    def refit_W_given_H(X: np.ndarray, H: np.ndarray) -> np.ndarray:
        try:
            Wt = np.linalg.lstsq(H.T + 1e-12, X.T, rcond=None)[0]
            W = Wt.T
        except Exception:
            W = X @ np.linalg.pinv(H + 1e-12)
        return np.clip(W, a_min=0.0, a_max=None)

    @staticmethod
    def normalize_factor_scales(W: np.ndarray, H: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
        scale = np.maximum(np.sum(H, axis=1), 1e-12)
        return np.clip(W * scale[None, :], 0.0, None), np.clip(H / scale[:, None], 0.0, None)

    @staticmethod
    def build_spatial_edges(valid_mask: Optional[np.ndarray], neighbor_type: str = "4-neighbor") -> np.ndarray:
        if valid_mask is None:
            return np.empty((0, 2), dtype=int)
        mask = np.asarray(valid_mask, dtype=bool)
        if not np.any(mask):
            return np.empty((0, 2), dtype=int)
        index_map = -np.ones(mask.shape, dtype=int)
        index_map[mask] = np.arange(int(mask.sum()))
        offsets = [(0, 1), (1, 0)]
        if neighbor_type == "8-neighbor":
            offsets += [(1, 1), (1, -1)]
        edges = []
        h, w = mask.shape
        for y in range(h):
            for x in range(w):
                if not mask[y, x]:
                    continue
                aa = index_map[y, x]
                for dy, dx in offsets:
                    yy = y + dy
                    xx = x + dx
                    if 0 <= yy < h and 0 <= xx < w and mask[yy, xx]:
                        bb = index_map[yy, xx]
                        if aa >= 0 and bb >= 0:
                            edges.append((int(aa), int(bb)))
        return np.asarray(edges, dtype=int) if edges else np.empty((0, 2), dtype=int)

    @staticmethod
    def smooth_W_by_graph(W: np.ndarray, edges: np.ndarray, lambda_spatial: float) -> np.ndarray:
        if edges is None or len(edges) == 0 or lambda_spatial <= 0:
            return W
        alpha = max(0.0, min(float(lambda_spatial) / (float(lambda_spatial) + 1.0), 0.95))
        neighbor_sum = np.zeros_like(W, dtype=float)
        counts = np.zeros((W.shape[0], 1), dtype=float)
        a = edges[:, 0]
        b = edges[:, 1]
        np.add.at(neighbor_sum, a, W[b])
        np.add.at(neighbor_sum, b, W[a])
        np.add.at(counts, a, 1.0)
        np.add.at(counts, b, 1.0)
        neighbor_avg = np.divide(neighbor_sum, np.maximum(counts, 1.0), out=np.zeros_like(W), where=counts > 0)
        return np.clip((1.0 - alpha) * W + alpha * neighbor_avg, a_min=0.0, a_max=None)

    @staticmethod
    def spatial_smoothness_score(W: Optional[np.ndarray], edges: Optional[np.ndarray]) -> float:
        if W is None or edges is None or len(edges) == 0:
            return float("nan")
        diffs = W[edges[:, 0]] - W[edges[:, 1]]
        return float(np.mean(np.sum(diffs ** 2, axis=1))) if diffs.size else float("nan")

    @staticmethod
    def reconstruction_error(X: np.ndarray, W: np.ndarray, H: np.ndarray) -> float:
        denom = max(float(np.linalg.norm(X)), 1e-12)
        return float(np.linalg.norm(X - W @ H) / denom)


class SpatialMolecularCartographyTab(QWidget):
    """MSI-native, segmentation-free spatial molecular cartography.

    This tab is intentionally isolated from the existing MSI Analysis Studio tabs.
    It is inspired by segmentation-free spatial-omics thinking, such as FICTURE,
    and is aware of MSI spatial co-clustering concepts such as TRIFASE, but it is
    not a direct implementation or copy of either method. The purpose here is a
    practical MSI Analysis Studio workflow: spatially informed molecular-domain
    discovery, interpretable m/z modules, and interactive ROI/mask generation.
    """

    def __init__(self, shared_state: SharedImageState, status_label: QLabel) -> None:
        super().__init__()
        self.shared_state = shared_state
        self.status_label = status_label

        # Matrix/data state
        self.X_raw: Optional[np.ndarray] = None
        self.X_model: Optional[np.ndarray] = None
        self.X_valid_filtered: Optional[np.ndarray] = None
        self.mz_values: np.ndarray = np.asarray([], dtype=float)
        self.filtered_mz_values: np.ndarray = np.asarray([], dtype=float)
        self.image_shape: Optional[tuple[int, int]] = None
        self.full_image_shape: Optional[tuple[int, int]] = None
        self.crop_rect_used: Optional[tuple[int, int, int, int]] = None
        self.valid_pixel_mask: Optional[np.ndarray] = None
        self.feature_mask: Optional[np.ndarray] = None
        self.pixel_coords: Optional[np.ndarray] = None
        self.graph_edges: np.ndarray = np.empty((0, 2), dtype=int)

        # Model/result state
        self.W: Optional[np.ndarray] = None
        self.H: Optional[np.ndarray] = None
        self.factor_maps: list[np.ndarray] = []
        self.factor_maps_smoothed: list[np.ndarray] = []
        self.factor_maps_normalized: list[np.ndarray] = []
        self.domain_map: Optional[np.ndarray] = None
        self.domain_confidence: Optional[np.ndarray] = None
        self.connected_components: list[dict] = []
        self.domain_labels: dict[int, str] = {}
        self.hidden_domains: set[int] = set()
        self.top_mz_table = pd.DataFrame()
        self.domain_summary_table = pd.DataFrame()
        self.metrics: dict = {}

        # Module state for co-clustering / m/z module mode
        self.mz_module_labels: Optional[np.ndarray] = None
        self.module_maps: list[np.ndarray] = []
        self.mz_module_table = pd.DataFrame()
        self.domain_module_association = pd.DataFrame()
        self.error_history: list[float] = []
        self.smoothness_history: list[float] = []
        self.active_cartography_view: str = "domain"
        self.cartography_worker: Optional[CartographyWorker] = None

        outer_layout = QVBoxLayout(self)
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
